import CNetMicSupport
import CoreAudio
import Foundation
import Testing

@testable import NetMicKit
@testable import NetMicProtocol

@Suite struct ReceiverStatsTests {
    /// Feeds packets of 240 frames generated by a sender clock running at
    /// (1 + ppm) and arriving with uniform jitter.
    func simulate(ppm: Double, seconds: Double, jitter: Double, drop: Set<UInt32> = [], seed: UInt64 = 7)
        -> ReceiverStats
    {
        var rng = SplitMix(seed: seed)
        var s = ReceiverStats()
        let rate = 48000 * (1 + ppm * 1e-6)
        let count = UInt32(seconds * rate / 240)
        for seq in 0..<count where !drop.contains(seq) {
            let pos = UInt64(seq) * 240
            let arrival = 1000 + Double(pos) / rate + 0.001 + rng.next() * jitter
            s.record(seq: seq, streamId: 1, samplePos: pos, arrival: arrival)
        }
        return s
    }

    @Test func driftEstimate() {
        for ppm in [-120.0, -30, 0, 45, 200] {
            let s = simulate(ppm: ppm, seconds: 120, jitter: 0.002)
            let est = try! #require(s.driftPpm)
            #expect(abs(est - ppm) < 1.0, "estimated \(est) for \(ppm)")
        }
    }

    @Test func driftNeedsTenSeconds() {
        #expect(simulate(ppm: 50, seconds: 5, jitter: 0).driftPpm == nil)
    }

    @Test func jitterIsMeasured() {
        #expect(simulate(ppm: 0, seconds: 10, jitter: 0).jitter < 1e-9)
        let j = simulate(ppm: 0, seconds: 10, jitter: 0.004).jitter
        #expect(j > 0.0008 && j < 0.002)  // E|U1-U2| for U(0,4ms) = 1.33 ms
    }

    @Test func lossCounted() {
        let s = simulate(ppm: 0, seconds: 10, jitter: 0, drop: [5, 6, 100])
        #expect(s.lost == 3)
        #expect(s.packets == 2000 - 3)
        #expect(s.reordered == 0)
    }

    @Test func reorderAndDuplicates() {
        var s = ReceiverStats()
        for seq: UInt32 in [0, 1, 3, 2, 4, 4, 5, 1] {
            s.record(seq: seq, streamId: 9, samplePos: UInt64(seq) * 240, arrival: Double(seq) * 0.005)
        }
        #expect(s.packets == 6)
        #expect(s.duplicates == 2)
        #expect(s.reordered == 1)
        #expect(s.lost == 0)
    }

    @Test func streamChangeResets() {
        var s = ReceiverStats()
        for seq: UInt32 in 0..<10 { s.record(seq: seq, streamId: 1, samplePos: UInt64(seq) * 240, arrival: 0) }
        for seq: UInt32 in 0..<3 { s.record(seq: seq + 500, streamId: 2, samplePos: UInt64(seq) * 240, arrival: 1) }
        #expect(s.streamChanges == 1)
        #expect(s.packets == 3)
        #expect(s.lost == 0)
    }
}

@Suite struct RingTests {
    /// Builds a deinterleaved buffer list (one channel per buffer) and runs body.
    func withABL(_ channels: [[Float]], _ body: (UnsafePointer<AudioBufferList>) -> Void) {
        let abl = AudioBufferList.allocate(maximumBuffers: channels.count)
        defer { free(abl.unsafeMutablePointer) }
        var storage = channels
        storage.withUnsafeMutableBufferPointer { chans in
            for i in 0..<chans.count {
                chans[i].withUnsafeMutableBufferPointer { p in
                    abl[i] = AudioBuffer(mNumberChannels: 1, mDataByteSize: UInt32(p.count * 4),
                                         mData: UnsafeMutableRawPointer(p.baseAddress))
                }
            }
            body(abl.unsafePointer)
        }
    }

    func readAll(_ ring: OpaquePointer) -> [Float] {
        var out = [Float](repeating: 0, count: 64)
        let n = Int(nm_ring_read(ring, &out, 64))
        return Array(out.prefix(n))
    }

    @Test func selectAndMix() {
        let ring = nm_ring_create(16)!
        defer { nm_ring_destroy(ring) }
        withABL([[1, 2, 3], [3, 4, 5]]) { abl in
            #expect(nm_ring_push_abl(ring, abl, 3, 1) == 3)
            #expect(readAll(ring) == [3, 4, 5])
            #expect(nm_ring_push_abl(ring, abl, 3, -1) == 3)
            #expect(readAll(ring) == [2, 3, 4])
            #expect(nm_ring_push_abl(ring, abl, 3, 7) == 3)  // out of range → silence
            #expect(readAll(ring) == [0, 0, 0])
        }
    }

    @Test func interleavedBuffer() {
        let ring = nm_ring_create(16)!
        defer { nm_ring_destroy(ring) }
        var data: [Float] = [1, 10, 2, 20, 3, 30]  // 2 interleaved channels, 3 frames
        data.withUnsafeMutableBufferPointer { p in
            var abl = AudioBufferList(mNumberBuffers: 1,
                                      mBuffers: AudioBuffer(mNumberChannels: 2, mDataByteSize: 24, mData: p.baseAddress))
            #expect(nm_ring_push_abl(ring, &abl, 3, 1) == 3)
            #expect(readAll(ring) == [10, 20, 30])
        }
    }

    @Test func overflowDropsAndCounts() {
        let ring = nm_ring_create(4)!
        defer { nm_ring_destroy(ring) }
        withABL([[1, 2, 3, 4, 5, 6]]) { abl in
            #expect(nm_ring_push_abl(ring, abl, 6, 0) == 4)
            #expect(nm_ring_overflows(ring) == 2)
            #expect(readAll(ring) == [1, 2, 3, 4])
            #expect(nm_ring_push_abl(ring, abl, 3, 0) == 3)  // wraps around
            #expect(readAll(ring) == [1, 2, 3])
        }
    }
}

@Suite struct SocketTests {
    @Test func loopbackRoundTrip() throws {
        let a = try UDPSocket(port: 0)
        let b = try UDPSocket(port: 0, broadcast: true)
        let pkt = Packet.subscribe(token: .zero, seq: 3)
        #expect(b.send(pkt, to: SocketAddress("127.0.0.1", port: a.localPort)!))
        let got = try #require(a.receive(timeoutMs: 1000))
        #expect(got.bytes == pkt)
        #expect(got.from.ipString == "127.0.0.1")
        #expect(got.from.port == b.localPort)
        #expect(a.receive(timeoutMs: 10) == nil)
    }

    @Test func addressParsing() {
        #expect(SocketAddress("192.168.1.20", port: 5)?.ip == 0xC0A8_0114)
        #expect(SocketAddress("192.168.1.20", port: 5)?.description == "192.168.1.20:5")
        #expect(SocketAddress("nope", port: 5) == nil)
    }
}

struct SplitMix {
    var state: UInt64
    init(seed: UInt64) { state = seed }
    mutating func next() -> Double {
        state &+= 0x9E37_79B9_7F4A_7C15
        var z = state
        z = (z ^ (z >> 30)) &* 0xBF58_476D_1CE4_E5B9
        z = (z ^ (z >> 27)) &* 0x94D0_49BB_1331_11EB
        return Double((z ^ (z >> 31)) >> 11) / Double(1 << 53)
    }
}
